import{_ as e,o as i,c as t,a as l}from"./chunks/framework.Ld7uezS_.js";const h=JSON.parse('{"title":"职业标准映射与版本过渡成果","description":"","frontmatter":{},"headers":[],"relativePath":"outputs/overview-2026-08-21-standard-mapping-round4.md","filePath":"outputs/overview-2026-08-21-standard-mapping-round4.md","lastUpdated":1787292351000}'),o={name:"outputs/overview-2026-08-21-standard-mapping-round4.md"};function r(d,a,n,p,s,u){return i(),t("div",null,[...a[0]||(a[0]=[l('<h1 id="职业标准映射与版本过渡成果" tabindex="-1">职业标准映射与版本过渡成果 <a class="header-anchor" href="#职业标准映射与版本过渡成果" aria-label="Permalink to &quot;职业标准映射与版本过渡成果&quot;">​</a></h1><p>日期：2026-08-21</p><h2 id="本轮结论" tabindex="-1">本轮结论 <a class="header-anchor" href="#本轮结论" aria-label="Permalink to &quot;本轮结论&quot;">​</a></h2><p>本轮尝试读取《消防设施操作员国家职业技能标准（2019年版）》并提取检测维修保养方向 2.1—5.3 条目。官方 PDF 为图像/压缩内容，当前无法可靠读取完整正文，因此没有伪造页码、原句或逐条技能要求。</p><p>公开检索摘要可以交叉确认 2019 年版包含：</p><ul><li>设施操作 2.1 火灾自动报警系统、2.2 自动灭火系统、2.3 其他消防设施；</li><li>设施保养 3.1—3.3；</li><li>设施维修 4.1—4.3；</li><li>设施检测 5.1—5.3；</li><li>检测维修保养方向的四项核心职业功能。</li></ul><p>这些摘要仅用于交叉定位，不替代标准 PDF 原文。</p><h2 id="发现的版本过渡" tabindex="-1">发现的版本过渡 <a class="header-anchor" href="#发现的版本过渡" aria-label="Permalink to &quot;发现的版本过渡&quot;">​</a></h2><p>消防职业技能鉴定考试网已公开《消防设施操作员国家职业标准（2026年版）》文件，公开信息显示自 2026-10-01 起施行。</p><p>当前日期为 2026-08-21，因此：</p><ul><li>2026-10-01 前，本站仍以 2019 年版作为当前学习基线；</li><li>2026-10-01 后，必须重新核对职业方向、申报条件、技能要求、知识要求和考核口径；</li><li>不能把 2019 年版和 2026 年版混写成一个标准；</li><li>2026 年版当前仅登记为即将生效版本，未将其条目写入现行映射。</li></ul><h2 id="修改文件" tabindex="-1">修改文件 <a class="header-anchor" href="#修改文件" aria-label="Permalink to &quot;修改文件&quot;">​</a></h2><ul><li><code>sources.md</code></li><li><code>exam-guide.md</code></li><li><code>standard-mapping.md</code></li><li><code>outputs/overview-2026-08-21-standard-mapping-round4.md</code></li></ul><h2 id="后续" tabindex="-1">后续 <a class="header-anchor" href="#后续" aria-label="Permalink to &quot;后续&quot;">​</a></h2><p>待获取可搜索文本、清晰页面图片或 OCR 文本后，再逐条补录 2.1—5.3 的标准编号、页码、技能要求和相关知识要求，并同步课程页与训练题映射。</p>',15)])])}const m=e(o,[["render",r]]);export{h as __pageData,m as default};
